package queue

type Queue struct { mu sync.Mutex }

func (q *Queue) Wait(ctx context.Context) {
	q.mu.Lock()
	defer q.mu.Unlock()
	<-ctx.Done()
}

package render

func Labels(users []User) []string {
	labels := []string{}
	for _, user := range users {
		labels = append(labels, fmt.Sprintf("%s:%d", user.Name, user.ID))
	}
	return labels
}

package orders

func Load(ctx context.Context, store Store, orders []Order) error {
	for _, order := range orders {
		if _, err := store.Customer(ctx, order.CustomerID); err != nil {
			return err
		}
	}
	return nil
}

package billing

func (s *Service) Charge(ctx context.Context, request Request) error {
	return s.gateway.Charge(ctx, request.Amount)
}

package account

func (s *Service) Delete(ctx context.Context, id string) error {
	return s.repo.Delete(ctx, id)
}

package status

func Label() string {
	return "ready"
}

package format

func Trim(value string) string {
	return strings.TrimSpace(value)
}

package cleanup

func Remove(ctx context.Context, store Store, id string) error {
	return store.Remove(ctx, id)
}
